"use client";
import {CashierVariancePostingReview} from './cashier-variance-posting-review';
import {CashierCustodyLinks} from './cashier-custody-links';
import {CashierJournalLink} from './cashier-journal-link';
import {CashierDepositTransferAction} from './cashier-deposit-transfer-action';
import {CashierLedgerPeriodSelect} from './cashier-ledger-period-select';
import {readDepositTransferPreview} from '@/lib/cashier-deposit-transfer';
import {useEffect,useRef,useState} from 'react';
import {hotelClient,hotelRpc,usd} from '@/lib/pilot';
import type {HandoffScope} from '@/lib/cashier-handoff';
import {CashierLedgerMappingSelect} from './cashier-ledger-mapping-select';
import {readCashierLedgerMappings} from '@/lib/cashier-ledger-mappings';
type Mapping=ReturnType<typeof readCashierLedgerMappings>['entries'][number];
export function CashierDepositLedgerReview({scope,deposit,bank,amount}:{scope:HandoffScope;deposit:string;bank:string;amount:string}){
 const [pending,setPending]=useState(false);
 const [posting,setPosting]=useState<{period:string;date:string}|null>(null),[preview,setPreview]=useState<Record<string,unknown>|null>(null);
 const [mapping,setMapping]=useState<Mapping|null>(null),[review,setReview]=useState<{blockers:string[];sources:number;openingSessions:string[];custodySessions:string[];variances:{session:string;amount:string}[]}|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState('');const alive=useRef(false),lock=useRef(false);
 useEffect(()=>{alive.current=true;return()=>{alive.current=false}},[]);
 async function inspect(){if(lock.current||pending||!mapping)return;lock.current=true;setBusy(true);setReview(null);setPosting(null);setPreview(null);setError('');try{
 const user=await hotelClient().auth.getUser();if(user.error||user.data.user?.id!==scope.actor)throw Error('Sign-in changed. Refresh deposits.');
 const response=await hotelRpc('review_deposit_ledger_sources',{p_tenant:scope.tenant,p_property:scope.property,p_deposit:deposit,p_mapping:mapping.id});
 if(!response||typeof response!=='object'||Array.isArray(response))throw Error('Invalid deposit review.');const v=response as Record<string,unknown>;
 if(v.schema_version!==1||v.tenant_id!==scope.tenant||v.property_id!==scope.property||v.actor_id!==scope.actor||v.deposit_id!==deposit||v.mapping_id!==mapping.id||v.amount_minor!==amount||!Array.isArray(v.blockers)||!v.blockers.every((x:unknown)=>typeof x==='string'&&x.trim())||!Array.isArray(v.source_reviews)||!v.source_reviews.every((s:unknown)=>!!s&&typeof s==='object'&&!Array.isArray(s)&&(s as Record<string,unknown>).tenant_id===scope.tenant&&(s as Record<string,unknown>).property_id===scope.property&&(s as Record<string,unknown>).actor_id===scope.actor)||(v.blockers.length===0&&v.source_reviews.length===0)||v.sources_reconciled!==(v.blockers.length===0))throw Error('Deposit accounting review changed. Refresh and try again.');
 const again=await hotelClient().auth.getUser();if(again.error||again.data.user?.id!==scope.actor)throw Error('Sign-in changed. Refresh deposits.');if(alive.current)setReview({variances:(v.source_reviews as Record<string,unknown>[]).filter(s=>typeof s.variance_minor==='string'&&/^-?[1-9][0-9]*$/.test(s.variance_minor)&&typeof s.session_id==='string'&&/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(s.session_id)).map(s=>({session:s.session_id as string,amount:s.variance_minor as string})),blockers:v.blockers as string[],sources:v.source_reviews.length,custodySessions:(v.source_reviews as Record<string,unknown>[]).filter(s=>typeof s.custody_movement_count==='number'&&s.custody_movement_count>0&&typeof s.session_id==='string'&&/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(s.session_id)).map(s=>s.session_id as string),openingSessions:(v.source_reviews as Record<string,unknown>[]).filter(s=>typeof s.opening_minor==='string'&&/^[1-9][0-9]*$/.test(s.opening_minor)&&typeof s.session_id==='string'&&/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(s.session_id)).map(s=>s.session_id as string)});
 }catch(e){if(alive.current)setError(e instanceof Error?e.message:'Unable to review deposit accounting.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 async function prepare(){if(lock.current||pending||!mapping||!posting)return;lock.current=true;setBusy(true);setPreview(null);setError('');try{
 const user=await hotelClient().auth.getUser();if(user.error||user.data.user?.id!==scope.actor)throw Error('Sign-in changed. Refresh deposits.');
 const value=await hotelRpc('preview_deposit_transfer',{p_tenant:scope.tenant,p_property:scope.property,p_deposit:deposit,p_mapping:mapping.id,p_period:posting.period,p_date:posting.date});
 const parsed=readDepositTransferPreview(value,{scope,deposit,mapping:mapping.id,period:posting.period,date:posting.date,amount,custody:mapping.custody.id,transit:mapping.transit.id});
 const again=await hotelClient().auth.getUser();if(again.error||again.data.user?.id!==scope.actor)throw Error('Sign-in changed. Refresh deposits.');if(alive.current)setPreview(parsed);
 }catch(e){if(alive.current)setError(e instanceof Error?e.message:'Unable to prepare transfer.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 return <details><summary>Review deposit accounting</summary><p>Deposit amount: {usd(Number(amount))}</p><CashierLedgerMappingSelect scope={scope} bank={bank} disabled={busy||pending} onSelect={m=>{setMapping(m);setReview(null);setPosting(null);setPreview(null);setError('')}}/><button type="button" disabled={busy||pending||!mapping} onClick={()=>void inspect()}>Check cash sources</button>{error&&<p role="alert">{error}</p>}{review&&<div role="status"><p>{review.sources} drawer source{review.sources===1?'':'s'} reviewed.</p>{review.blockers.length?<><p>Resolve these items before posting:</p><ul>{review.blockers.map((b,i)=><li key={i}>{b}</li>)}</ul></>:<p>Cash sources reconcile. A posting date and final approval are still required.</p>}</div>}{review&&review.variances.map(v=><CashierVariancePostingReview key={v.session} scope={scope} session={v.session} bank={bank} amount={v.amount}/>)}{review&&mapping&&review.custodySessions.map(session=><CashierCustodyLinks key={"custody:"+session+":"+mapping.id} scope={scope} session={session} account={mapping.custody.id} disabled={busy||pending} onSaved={()=>{setPreview(null);setPosting(null)}}/>)}{review&&mapping&&review.openingSessions.map(session=><CashierJournalLink key={session+":"+mapping.id} source={{scope,kind:"opening",source:session,account:mapping.custody.id}} disabled={busy||pending} onSaved={()=>{setPreview(null);setPosting(null)}}/>)}{review&&!review.blockers.length&&<><CashierLedgerPeriodSelect key={[scope.tenant,scope.property,scope.actor,deposit].join(':')} scope={scope} disabled={busy||pending} onSelect={v=>{setPosting(v);setPreview(null)}}/><button type="button" disabled={busy||pending||!mapping||!posting} onClick={()=>void prepare()}>Preview deposit transfer</button></>}{preview&&mapping&&posting&&<section aria-label="Deposit transfer preview"><h4>Transfer ready for review</h4><p>Posting date: {posting.date}</p><p>Debit {mapping.transit.name}: {usd(Number(amount))}</p><p>Credit {mapping.custody.name}: {usd(Number(amount))}</p><p>This preview has not posted a journal or confirmed bank settlement.</p></section>}<CashierDepositTransferAction key={[scope.tenant,scope.property,scope.actor,deposit].join(':')} scope={scope} deposit={deposit} selection={mapping&&posting?{scope,deposit,mapping:mapping.id,period:posting.period,date:posting.date,amount,custody:mapping.custody.id,transit:mapping.transit.id}:null} preview={preview} onPending={setPending}/></details>
}
